function borderArray(s) {
  const lps = new Array(s.length).fill(0)
  let len = 0
  for (let i = 1; i + 1 <= s.length; i++) {
    while (len > 0 && s[i] !== s[len]) {
      len = lps[len - 1]
    }
    if (s[i] === s[len]) {
      len += 1
    }
    lps[i] = len
  }
  return lps
}

